    background-color: #fefefe;
    margin: 15% auto;
    padding: 20px;
    border: 1px solid #888;
    width: 80%;
    max-width: 600px;
  }
  .chat-history {
    list-style-type: none;
    padding: 0;
  }
  .chat-history li {
    padding: 8px;
    margin-bottom: 2px;
    border-radius: 4px;
  }
