        std::transform(line.begin(), line.end(), line.begin(), ::tolower);

        // Count occurrences of the search word
        size_t pos = 0;
        while ((pos = line.find(search_word, pos)) != std::string::npos) {
            count++;
            pos += search_word.length();
        }
    }

    // Close the file
    file.close();

    // Print the result
    std::cout << "Number of occurrences of '" << search_word << "' in " << filename << ": " << count << std::endl;

    return 0;
}
```

